/**
 * @method
 * @name fn_checkLpAdd
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_checkLpAdd = function() {
    if (getByteLength(form["lpStrtDd"].getValue()) == 0) {
        alert("추가유동성공급기간_1 을 입력해 주십시오.");
        form["lpStrtDd"].focus();
        return false;
    }
    if (form.sysdate.getValue() >= form["lpStrtDd"].getValue()) {
        alert("추가유동성공급기간_1 을 현재일이후로 입력해 주십시오.");
        form["lpStrtDd"].focus();
        return false;
    }
    if (getByteLength(form["lpEndDd"].getValue()) == 0) {
        alert("추가유동성공급기간_1 을 입력해 주십시오.");
        form["lpEndDd"].focus();
        return false;
    }
    if (form.sysdate.getValue() >= form["lpEndDd"].getValue()) {
        alert("추가유동성공급기간_1 을 현재일이후로 입력해 주십시오.");
        form["lpEndDd"].focus();
        return false;
    }
    if (form["lpStrtDd"].getValue() >= form["lpEndDd"].getValue()) {
        alert("추가유동성공급기간_1 의 시작일을 종료일이전으로  입력해 주십시오.");
        form["lpStrtDd"].focus();
        return false;
    }
    return true;
};
/**
 * @method
 * @name fn_CommaValueAll
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CommaValueAll = function() {
    fn_ObjValueSetComma(form["isuPrc"]); //   발행가격                         
    fn_ObjValueSetComma(form["isuShrs"]); //   발행증권수                       

    fn_ObjValueSetComma(form["elwConvRto"]); //   ELW전환비율                      
    fn_ObjValueSetComma(form["elwUlyBasPrc"]); //   ELW기초자산기초가격              
    fn_ObjValueSetComma(form["elwExerPrc"]); //   ELW행사가격                      
    fn_ObjValueSetComma(form["elwPrcUpPartcRt"]); //   ELW가격상승참가율                
    fn_ObjValueSetComma(form["elwCompnsRt"]); //   ELW보상률                        
    fn_ObjValueSetComma(form["elwFinalPayVal"]); //   ELW확정지급액                    
    fn_ObjValueSetComma(form["riskfreIntRt"]); //   무위험이자율                     
    fn_ObjValueSetComma(form["elwDivRt"]); //   ELW배당률                        
    fn_ObjValueSetComma(form["applVoltRto"]); //   적용변동성비율                   
    fn_ObjValueSetComma(form["ordSpdRto"]); //   호가스프레드                     

    //fn_ObjValueSetComma(form["pubofrAmt"   ]); //  공모금액                          
    //fn_ObjValueSetComma(form["subsAmt"     ]); //  청약금액                          
    //fn_ObjValueSetComma(form["subsRto"     ]); //  응모비율                          
    //fn_ObjValueSetComma(form["totPubofrAmt"]); //  총공모금액                        
    //fn_ObjValueSetComma(form["fndSuplyAmt" ]); //  자금조달금액                      

    fn_ObjValueSetComma(form["addIsuShrs"]); //   추가발행주식수                     
    fn_ObjValueSetComma(form["isuTotPrc"]); //   최초발행총액                     
    fn_ObjValueSetComma(form["isuTotPrcAdd"]); //   추가발행총액                     
    fn_ObjValueSetComma(form["isuTotalAmt"]); //   총발행수량                     
    fn_ObjValueSetComma(form["isuTotalPrc"]); //   총발행총액                     

    /*
	for(var i = 0 ; i < form["elwPubofrCostTpNm"].length ; i++) {
		if( form["elwPubofrCostTpNm"][i].value == '' ) continue ;
		fn_ObjValueSetComma(form["isuExps"][i]); 
	}	           
*/

    //fn_ObjValueSetComma(form["netIncm"    ]); //   순수입금[ (1) - (2) ]                     

};
